#define KELLY_DECOMP_FULL_FEMENU_ENTRY
#define KELLY_DECOMP_FULL_FEMULTI_MENU
#include "KS/SRC/ks/FEMenu_shared.h"
#undef KELLY_DECOMP_FULL_FEMULTI_MENU
#undef KELLY_DECOMP_FULL_FEMENU_ENTRY
#include "KS/SRC/ks/GraphicalMenuSystem_shared.h"

#define assert(condition) ((void)0)

class FEEntityManager {
public:
    bool InFlyin();
    void ExitState();
};

class FEManager {
    char padding[12];
public:
    FEEntityManager *em;
};

class OptionsMenu : public FEMenu {};
class MultiplayerMenu : public FEMenu {};
class FreesurfMenu : public FEMenu {};
class CareerMenu : public FEMenu {};
class MultiSubMenu;

class MainFrontEnd : public FEMultiMenu {
public:
    enum {
        MainFreeEntry,
        MainCareerEntry,
        MainMultiEntry,
        MainExtrasEntry,
        MainOpEntry,
        MainEnd
    };

private:
    FEManager *manager;
    GraphicalMenuSystem *sys;
    FEMenuEntry *entry_list[MainEnd];
    entity *ents[MainEnd];
    PanelQuad *boxes[MainEnd][9];
    PanelQuad *circles[MainEnd][1];
    PanelQuad *lines[MainEnd][3];

public:
    OptionsMenu *Options;
    MultiplayerMenu *Multi;
    FreesurfMenu *Freesurf;
    CareerMenu *career_menu;
    MultiSubMenu *multi_sub;

    virtual void MakeActive(FEMenu *menu);
    virtual void Select(int entry_index);
};

void MainFrontEnd::Select(int entry_index)
{
	if(manager->em->InFlyin()) return;
	if(active)
		active->Select(active->highlighted->entry_num);
	else
	{
		if(entry_index != MainExtrasEntry && entry_index != MainOpEntry && entry_index != MainMultiEntry)
			manager->em->ExitState();
		sys->multiplayer = (entry_index == MainMultiEntry);

		stringx tmp;
		switch(entry_index)
		{
		case MainCareerEntry:	career_menu->Select(career_menu->highlighted->entry_num); break;
		case MainFreeEntry:		Freesurf->Select(Freesurf->highlighted->entry_num); break;
		case MainMultiEntry:	Multi->Select(Multi->highlighted->entry_num); break;
		case MainExtrasEntry:	sys->MakeActive(GraphicalMenuSystem::ExtrasMenu); break;
		case MainOpEntry:		MakeActive(Options); break;
		default: assert(0);
		}
	}
}
